// Currency formatter
window.formatCurrency = (amount, currency = 'USD', locale = 'en-US') => {
    const currencyMap = {
        'USD': 'USD',
        'EUR': 'EUR',
        'GBP': 'GBP',
        'JPY': 'JPY',
        'BRL': 'BRL',
        'ARS': 'ARS',
        'UYU': 'UYU',
        'GOLD': 'XAU' // Using XAU code for gold
    };

    // Default to USD if currency not found
    const currencyCode = currencyMap[currency] || 'USD';
    
    return new Intl.NumberFormat(locale, {
        style: 'currency',
        currency: currencyCode,
        minimumFractionDigits: ['JPY'].includes(currencyCode) ? 0 : 2,
        maximumFractionDigits: ['JPY'].includes(currencyCode) ? 0 : 2
    }).format(amount);
};

// Format GoldStay tokens
window.formatGoldStay = (amount) => {
    return amount.toFixed(4) + ' GOLD';
};

// Global CSRF token handling for AJAX requests
window.axios = __webpack_require__(/*! axios */ "./node_modules/axios/index.js");
window.axios.defaults.headers.common['X-Requested-With'] = 'XMLHttpRequest';

const token = document.head.querySelector('meta[name="csrf-token"]');
if (token) {
    window.axios.defaults.headers.common['X-CSRF-TOKEN'] = token.content;
} else {
    console.error('CSRF token not found: https://laravel.com/docs/csrf#csrf-x-csrf-token');
}

// GoldStay Web3 integration
window.initGoldStayWallet = async () => {
    try {
        if (window.ethereum) {
            await window.ethereum.request({ method: 'eth_requestAccounts' });
            const provider = new ethers.providers.Web3Provider(window.ethereum);
            const signer = provider.getSigner();
            
            // Contract details from env
            const contractAddress = document.querySelector('meta[name="goldstay-contract"]')?.content;
            if (!contractAddress) {
                throw new Error('GoldStay contract address not found');
            }
            
            // Simplified ABI for ERC-20 token
            const abi = [
                "function balanceOf(address owner) view returns (uint256)",
                "function transfer(address to, uint256 amount) returns (bool)",
                "function name() view returns (string)",
                "function symbol() view returns (string)",
                "function decimals() view returns (uint8)"
            ];
            
            const contract = new ethers.Contract(contractAddress, abi, signer);
            
            return { provider, signer, contract };
        } else {
            throw new Error('MetaMask or compatible Web3 provider not found');
        }
    } catch (error) {
        console.error('Error initializing GoldStay wallet:', error);
        return null;
    }
};

// Investment chart initializer
window.initInvestmentChart = (elementId, data, options = {}) => {
    const ctx = document.getElementById(elementId).getContext('2d');
    
    // Default chart options
    const defaultOptions = {
        type: 'line',
        data: {
            labels: data.labels || [],
            datasets: [{
                label: data.label || 'Value',
                data: data.values || [],
                backgroundColor: options.backgroundColor || 'rgba(242, 180, 53, 0.2)',
                borderColor: options.borderColor || 'rgba(242, 180, 53, 1)',
                borderWidth: options.borderWidth || 2,
                tension: options.tension || 0.4,
                pointRadius: options.pointRadius || 0
            }]
        },
        options: {
            responsive: true,
            maintainAspectRatio: false,
            plugins: {
                legend: {
                    display: options.showLegend || false
                },
                tooltip: {
                    mode: 'index',
                    intersect: false
                }
            },
            scales: {
                x: {
                    display: options.showXAxis !== undefined ? options.showXAxis : true,
                    grid: {
                        display: false
                    }
                },
                y: {
                    display: options.showYAxis !== undefined ? options.showYAxis : true,
                    grid: {
                        borderDash: [2],
                        drawBorder: false
                    }
                }
            }
        }
    };
    
    // Merge with custom options
    const chartOptions = Object.assign({}, defaultOptions, options);
    
    return new Chart(ctx, chartOptions);
};

// File upload with preview
window.setupFileUpload = (inputId, previewId) => {
    const input = document.getElementById(inputId);
    const preview = document.getElementById(previewId);
    
    if (!input || !preview) return;
    
    input.addEventListener('change', function(e) {
        preview.innerHTML = '';
        
        const files = e.target.files;
        if (files.length > 0) {
            for (let i = 0; i < files.length; i++) {
                const file = files[i];
                
                if (file.type.match('image.*')) {
                    const reader = new FileReader();
                    
                    reader.onload = function(e) {
                        const img = document.createElement('img');
                        img.src = e.target.result;
                        img.classList.add('h-20', 'w-20', 'object-cover', 'rounded-lg', 'mr-2', 'mb-2');
                        preview.appendChild(img);
                    };
                    
                    reader.readAsDataURL(file);
                } else {
                    const fileIcon = document.createElement('div');
                    fileIcon.classList.add('h-20', 'w-20', 'flex', 'items-center', 'justify-center', 'bg-gray-100', 'rounded-lg', 'mr-2', 'mb-2');
                    fileIcon.innerHTML = `
                        <svg xmlns="http://www.w3.org/2000/svg" class="h-10 w-10 text-gray-400" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                            <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" />
                        </svg>
                    `;
                    preview.appendChild(fileIcon);
                }
            }
        }
    });
};

// Date picker initialization
window.initDatepicker = (selector, options = {}) => {
    const elements = document.querySelectorAll(selector);
    
    if (elements.length > 0) {
        elements.forEach(element => {
            flatpickr(element, {
                dateFormat: options.dateFormat || 'Y-m-d',
                altInput: options.altInput !== undefined ? options.altInput : true,
                altFormat: options.altFormat || 'd/m/Y',
                locale: options.locale || 'en',
                ...options
            });
        });
    }
};

// Alpine.js data components
window.initAlpineComponents = () => {
    // User menu dropdown
    window.userMenuData = function() {
        return {
            open: false,
            toggle() {
                this.open = !this.open;
            },
            close() {
                this.open = false;
            }
        };
    };
    
    // Mobile sidebar
    window.sidebarData = function() {
        return {
            open: false,
            toggle() {
                this.open = !this.open;
            },
            close() {
                this.open = false;
            }
        };
    };
    
    // Currency switcher
    window.currencySwitcherData = function() {
        return {
            currentCurrency: 'USD',
            currencies: ['USD', 'EUR', 'GBP', 'JPY', 'BRL', 'ARS', 'UYU', 'GOLD'],
            setCurrency(currency) {
                this.currentCurrency = currency;
                // You might want to save this preference or trigger other actions
            }
        };
    };
    
    // Notifications
    window.notificationsData = function() {
        return {
            open: false,
            notifications: [],
            unreadCount: 0,
            toggle() {
                this.open = !this.open;
            },
            close() {
                this.open = false;
            },
            markAsRead(id) {
                // Implementation to mark notification as read
                // This would typically involve an API call
                console.log('Marking notification as read:', id);
            },
            fetchNotifications() {
                // This would typically be an API call
                console.log('Fetching notifications');
            }
        };
    };
    
    // KYC Document Upload
    window.kycUploadData = function() {
        return {
            dragOver: false,
            files: [],
            documentType: '',
            uploading: false,
            
            handleDrop(e) {
                e.preventDefault();
                this.dragOver = false;
                
                Array.from(e.dataTransfer.files).forEach(file => {
                    if (this.isValidFile(file)) {
                        this.files.push(file);
                    }
                });
            },
            
            handleFileSelect(e) {
                Array.from(e.target.files).forEach(file => {
                    if (this.isValidFile(file)) {
                        this.files.push(file);
                    }
                });
            },
            
            isValidFile(file) {
                const validTypes = ['image/jpeg', 'image/png', 'image/jpg', 'application/pdf'];
                const maxSize = 5 * 1024 * 1024; // 5MB
                
                if (!validTypes.includes(file.type)) {
                    alert('Invalid file type. Please upload JPG, PNG or PDF files only.');
                    return false;
                }
                
                if (file.size > maxSize) {
                    alert('File is too large. Maximum size is 5MB.');
                    return false;
                }
                
                return true;
            },
            
            removeFile(index) {
                this.files.splice(index, 1);
            },
            
            uploadFiles() {
                if (this.files.length === 0 || !this.documentType) {
                    alert('Please select files and document type.');
                    return;
                }
                
                this.uploading = true;
                
                // This would typically be an API call
                setTimeout(() => {
                    console.log('Files uploaded:', this.files);
                    console.log('Document type:', this.documentType);
                    this.files = [];
                    this.documentType = '';
                    this.uploading = false;
                    alert('Files uploaded successfully!');
                }, 2000);
            }
        };
    };
};

